const menu=document.querySelector('.menu'),nav=document.querySelector('#nav');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open)});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open')){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.focus()}});
let year=2026,month=8,day=15,time='10:30 AM';const months=['January','February','March','April','May','June','July','August','September','October','November','December'];function label(){const date=new Date(year,month,day);document.querySelector('#timeLabel').textContent=date.toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'});document.querySelector('#badgeDate').textContent=day;document.querySelector('.cal-icon').firstChild.textContent=months[month].slice(0,3).toUpperCase();document.querySelector('#result').textContent='';document.querySelector('#confirm').innerHTML='Confirm time <span>→</span>'}function render(){document.querySelector('#monthLabel').textContent=months[month]+' '+year;const grid=document.querySelector('#days');grid.replaceChildren();const offset=(new Date(year,month,1).getDay()+6)%7;for(let i=0;i<offset;i++)grid.append(document.createElement('span'));for(let n=1;n<=new Date(year,month+1,0).getDate();n++){const b=document.createElement('button');b.textContent=n;const weekend=[0,6].includes(new Date(year,month,n).getDay());b.disabled=weekend;b.className=weekend?'':'available';b.setAttribute('aria-label',months[month]+' '+n+', '+year);b.setAttribute('aria-pressed',String(n===day));if(n===day)b.classList.add('active');b.addEventListener('click',()=>{day=n;render()});grid.append(b)}label()}function changeMonth(delta){month+=delta;if(month>11){month=0;year++}if(month<0){month=11;year--}day=1;while([0,6].includes(new Date(year,month,day).getDay()))day++;render()}document.querySelector('#prev').addEventListener('click',()=>changeMonth(-1));document.querySelector('#next').addEventListener('click',()=>changeMonth(1));document.querySelectorAll('[data-time]').forEach(b=>{b.setAttribute('aria-pressed',String(b.dataset.time===time));b.addEventListener('click',()=>{time=b.dataset.time;document.querySelectorAll('[data-time]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b))});label()})});document.querySelector('#confirm').addEventListener('click',()=>{document.querySelector('#result').textContent='Preview confirmed: '+months[month]+' '+day+' at '+time+'. No real meeting was booked.';document.querySelector('#confirm').textContent='✓ Time selected'});render();
const teams={Sales:['Less admin. More meaningful conversations.','Give prospects a direct path to your calendar, route meetings to the right person, and keep your team focused on building relationships.','sales'],Recruiting:['Your next great hire starts with hello.','Make it easy for candidates to find a time. Coordinate interviews across your team and keep the hiring process moving.','recruiting'],'Customer success':['Make every customer feel like a priority.','Give customers an easy way to connect for onboarding, check-ins, and support. Spend more time helping and less time coordinating.','customer-success']};const tabs=[...document.querySelectorAll('[data-tab]')];tabs.forEach((b,i)=>{b.id='team-tab-'+i;b.setAttribute('aria-controls','teamPanel');b.tabIndex=i===0?0:-1;b.addEventListener('click',()=>{tabs.forEach(x=>{x.setAttribute('aria-selected',String(x===b));x.tabIndex=x===b?0:-1});const [title,copy,slug]=teams[b.dataset.tab];document.querySelector('#teamTitle').textContent=title;document.querySelector('#teamText').textContent=copy;document.querySelector('#teamPanel').setAttribute('aria-labelledby',b.id);const link=document.querySelector('#teamLink');link.href='https://calendly.com/solutions/'+slug;link.textContent='Explore Calendly for '+b.dataset.tab.toLowerCase()+' ↗'});b.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const n=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[n].click();tabs[n].focus()}})});document.querySelector('#teamPanel').setAttribute('aria-labelledby',tabs[0].id);
